-- 观看次数分布：ad_log不限result；当日活跃为全集，保留0次玩家。
SELECT day AS "数据日期",ad_times AS "广告次数",users AS "人数",sum(users) OVER(PARTITION BY day) AS "当日活跃",ad_times*users AS "广告总次数",cast(round(1.000000*users/nullif(sum(users) OVER(PARTITION BY day),0),4) AS decimal(18,4)) AS "人数占比%",cast(round(1.000000*ad_times*users/nullif(sum(ad_times*users) OVER(PARTITION BY day),0),4) AS decimal(18,4)) AS "次数占比%" FROM (SELECT a.day,coalesce(v.views,0) ad_times,count(DISTINCT a.pid) users FROM (SELECT day,pid FROM (SELECT * FROM (SELECT e."$part_date" day,u.pid,u.reg_day,u.channel_id,e."$part_event" event_name,coalesce(nullif(e.ad_location_scene,''),nullif(e.ad_location_name,''),nullif(e.ad_location_id,''),'未知广告点') ad_point,coalesce(e.battle_type,'未知模式') battle_type,coalesce(nullif(e.battle_type_name,''),e.battle_type,'未知模式') battle_type_name,e.map_id,e.result ad_result,e.battle_result,e.battle_time,e.remain_screw_num,e."#duration" seconds FROM ta.v_event_54 e JOIN (SELECT "#user_id",pid,reg_day,channel_id FROM (SELECT r.*,cast(reg_day AS varchar) "$part_date" FROM (SELECT "#user_id", coalesce(nullif(nb_open_id,''),nullif("#account_id",''),cast("#user_id" AS varchar)) pid, date(min(first_login_time) OVER(PARTITION BY coalesce(nullif(nb_open_id,''),nullif("#account_id",''),cast("#user_id" AS varchar)))) reg_day, coalesce(first_value(channel_id) OVER(PARTITION BY coalesce(nullif(nb_open_id,''),nullif("#account_id",''),cast("#user_id" AS varchar)) ORDER BY first_login_time NULLS LAST),'未知') channel_id FROM ta.v_user_54 WHERE domain='release' AND game_name='yishuajiushangtou') r) registered WHERE ${PartDate:date2} AND ${Selector:selector3}) u ON e."#user_id"=u."#user_id" WHERE e.game_name='yishuajiushangtou' AND ${PartDate:date1}) population WHERE ${Selector:selector4}) e GROUP BY day,pid) a LEFT JOIN (SELECT day,pid,count(*) views FROM (SELECT * FROM (SELECT * FROM (SELECT e."$part_date" day,u.pid,u.reg_day,u.channel_id,e."$part_event" event_name,coalesce(nullif(e.ad_location_scene,''),nullif(e.ad_location_name,''),nullif(e.ad_location_id,''),'未知广告点') ad_point,coalesce(e.battle_type,'未知模式') battle_type,coalesce(nullif(e.battle_type_name,''),e.battle_type,'未知模式') battle_type_name,e.map_id,e.result ad_result,e.battle_result,e.battle_time,e.remain_screw_num,e."#duration" seconds FROM ta.v_event_54 e JOIN (SELECT "#user_id",pid,reg_day,channel_id FROM (SELECT r.*,cast(reg_day AS varchar) "$part_date" FROM (SELECT "#user_id", coalesce(nullif(nb_open_id,''),nullif("#account_id",''),cast("#user_id" AS varchar)) pid, date(min(first_login_time) OVER(PARTITION BY coalesce(nullif(nb_open_id,''),nullif("#account_id",''),cast("#user_id" AS varchar)))) reg_day, coalesce(first_value(channel_id) OVER(PARTITION BY coalesce(nullif(nb_open_id,''),nullif("#account_id",''),cast("#user_id" AS varchar)) ORDER BY first_login_time NULLS LAST),'未知') channel_id FROM ta.v_user_54 WHERE domain='release' AND game_name='yishuajiushangtou') r) registered WHERE ${PartDate:date2} AND ${Selector:selector3}) u ON e."#user_id"=u."#user_id" WHERE e.game_name='yishuajiushangtou' AND ${PartDate:date1}) population WHERE ${Selector:selector4}) e WHERE event_name='ad_log' AND ('${Variable5}'='全部' OR ad_point='${Variable5}')) e GROUP BY day,pid) v ON a.day=v.day AND a.pid=v.pid GROUP BY a.day,coalesce(v.views,0)) d ORDER BY day DESC,ad_times